#!/usr/bin/env node
// Regenerates lib/image-pools.gen.ts from the public/<pool>/ folders.
//
// Adding an image to an image pool is exactly: drop the file into the folder
// (nextjs/public/club-icons, nextjs/public/trophies, …) and redeploy — this
// script, run by `pnpm dev` and `pnpm build`, refreshes the manifest the
// pickers read. The generated file is committed (like app/api-types.gen.ts)
// so a fresh checkout typechecks and tests without a build first.

import { readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { dirname } from "node:path";
import { fileURLToPath } from "node:url";

const root = dirname(dirname(fileURLToPath(import.meta.url)));

// pool name → folder under public/ and the extensions it collects.
const POOLS = [
    { name: "club-icons", extensions: [".svg"] },
    { name: "trophies", extensions: [".png", ".webp", ".jpg", ".jpeg", ".gif", ".svg"] },
];

const manifest = {};
for (const { name, extensions } of POOLS) {
    const dir = join(root, "public", name);
    manifest[name] = readdirSync(dir)
        .filter(
            (f) =>
                !f.startsWith(".") &&
                extensions.some((ext) => f.toLowerCase().endsWith(ext)),
        )
        .sort();
}

const file = `// Generated by scripts/generate-image-pools.mjs from the public/<pool>/
// folders; regenerated on every \`pnpm dev\` and \`pnpm build\`. Do not edit —
// adding an image to the folder and redeploying is the whole change
// (see the pickers' help hints).
export const IMAGE_POOLS = ${JSON.stringify(manifest, null, 4).replace(/"/g, '"')} as const;

export type ImagePool = keyof typeof IMAGE_POOLS;
`;

const out = join(root, "lib", "image-pools.gen.ts");
writeFileSync(out, file);
console.log(`image pools: ${Object.entries(manifest).map(([k, v]) => `${k}=${v.length}`).join(", ")} -> lib/image-pools.gen.ts`);
